// Injection sécurisée dans NocoDB — anti-doublon par email
const nocoKey = '27IYCbJpwko4-PTps7jQpiA90Jklm6WGmPZ_2rlv';
const urlBase = 'http://nocodb:8080/api/v1/db/data/noco/p10jh0dkphkze90/mb6dwmaubxp21jp';

const items = $input.all();
const results = { added: 0, skipped: 0, errors: 0 };

for (const item of items) {
  const d = item.json;

  try {
    // Vérifier si email existe déjà
    const check = await helpers.httpRequest({
      method: 'GET',
      url: urlBase,
      qs: { where: '(contact_email,eq,' + d.email + ')', limit: 1 },
      headers: { 'xc-token': nocoKey },
      json: true
    });

    if (check.list && check.list.length > 0) {
      results.skipped++;
      continue; // Déjà dans la base
    }

    // Insérer le nouveau lead
    await helpers.httpRequest({
      method: 'POST',
      url: urlBase,
      headers: { 'xc-token': nocoKey, 'Content-Type': 'application/json' },
      body: {
        nom_societe: String(d.company || ''),
        contact_email: String(d.email || ''),
        url_site: String(d.url_site || ''),
        secteur: String(d.secteur || 'Tech / SaaS'),
        score_opportunite: d.score || 70,
        score_impact: d.score || 70,
        status: 'A SCANNER',
        last_scan_date: new Date().toISOString().split('T')[0]
      },
      json: true
    });

    results.added++;
    console.log('Ajouté:', d.company, d.email);

  } catch(e) {
    results.errors++;
    console.log('Erreur pour', d.email, ':', e.message);
  }
}

console.log('Résultat injection:', results);
return [{ json: {
  status: 'INJECTION_COMPLETE',
  added: results.added,
  skipped: results.skipped,
  errors: results.errors,
  timestamp: new Date().toISOString()
}}];

