    return r&&r.choices&&r.choices[0]?r.choices[0].message.content:'Indisponible';
  }catch(e){
    if(e.message&&e.message.includes('429')){
      await sleep(11000);
      try{const r2=await helpers.httpRequest({method:'POST',url:'https://api.groq.com/openai/v1/chat/completions',headers:{'Authorization':'Bearer '+key,'Content-Type':'application/json'},body:{model:'mixtral-8x7b-32768',max_tokens:720,temperature:temp,messages:[{role:'system',content:sys},{role:'user',content:prompt}]},json:true});return r2&&r2.choices&&r2.choices[0]?r2.choices[0].message.content:'[429 mixtral]';}catch(e2){
      await sleep(9000);
      try{const r3=await helpers.httpRequest({method:'POST',url:'https://api.groq.com/openai/v1/chat/completions',headers:{'Authorization':'Bearer '+key,'Content-Type':'application/json'},body:{model:'llama-3.1-8b-instant',max_tokens:640,temperature:0.7,messages:[{role:'system',content:sys},{role:'user',content:prompt}]},json:true});return r3&&r3.choices&&r3.choices[0]?r3.choices[0].message.content:'[429 triple]';}catch(e3){return '[429 triple final]';}}
    }
    return '[ERR] '+e.message;
  }
}

